rows.push(...[["Empresa", "Entreprise", "Company"], ["A Capiarcos", "Capiarcos", "About Capiarcos"], ["A empresa — Capiarcos", "L’entreprise — Capiarcos", "The company — Capiarcos"], ["A ORIGEM", "LES ORIGINES", "OUR ORIGINS"], ["CAPACIDADE DE RESPOSTA", "CAPACITÉ DE RÉPONSE", "CAPABILITY AND COMMITMENT"], ["EXCLUSIVIDADE E VERSATILIDADE", "EXCLUSIVITÉ ET POLYVALENCE", "INDIVIDUALITY AND VERSATILITY"], ["ATENDIMENTO PERSONALIZADO", "UN ACCOMPAGNEMENT PERSONNALISÉ", "PERSONAL SERVICE"], ["Apresentação da Capiarcos", "Présentation de Capiarcos", "Introducing Capiarcos"], ["Percurso da empresa", "Parcours de l’entreprise", "Company story"], ["DE 04", "SUR 04", "OF 04"], ["Conheça a Capiarcos: carpintaria desde 1998, fábrica própria e acompanhamento do projeto à montagem.", "Découvrez Capiarcos : menuiserie depuis 1998, production en interne et accompagnement de la conception à la pose.", "Discover Capiarcos: carpentry since 1998, in-house production and support from design to installation."], ["A Capiarcos – Sociedade Unipessoal de Carpintaria, Lda., fundada a 4 de maio de 1998, é uma empresa especializada em carpintaria e mobiliário por medida. Com uma abordagem flexível e orientada para cada projeto, permite ao cliente personalizar materiais, tipos de madeira, cores, acabamentos e outros detalhes, criando soluções adaptadas às características e necessidades de cada espaço.", "Capiarcos – Sociedade Unipessoal de Carpintaria, Lda., fondée le 4 mai 1998, est une entreprise spécialisée dans la menuiserie et le mobilier sur mesure. Grâce à une approche souple, adaptée à chaque projet, elle permet au client de personnaliser les matériaux, les essences de bois, les couleurs, les finitions et d’autres détails, pour créer des solutions répondant aux caractéristiques et aux besoins de chaque espace.", "Capiarcos – Sociedade Unipessoal de Carpintaria, Lda., founded on 4 May 1998, specialises in carpentry and bespoke furniture. With a flexible approach tailored to each project, the company gives clients the freedom to personalise materials, wood species, colours, finishes and other details, creating solutions suited to the character and needs of each space."], ["Dispõe de uma equipa especializada e de produção própria, o que lhe permite responder às exigências do mercado, assegurando os prazos de execução e os níveis de qualidade definidos para cada projeto. A proximidade com o cliente é mantida ao longo de todo o processo, desde o primeiro contacto e definição da solução até à produção e montagem final.", "Elle dispose d’une équipe spécialisée et de sa propre unité de production, ce qui lui permet de répondre aux exigences du marché tout en respectant les délais et les niveaux de qualité définis pour chaque projet. La proximité avec le client est préservée tout au long du processus, du premier contact et de la définition de la solution jusqu’à la fabrication et à la pose finale.", "With a skilled team and its own production facilities, the company can meet market demands while delivering within the agreed timescales and quality standards for each project. Close contact with the client is maintained throughout the process, from the first conversation and definition of the solution through to production and final installation."], ["O mobiliário é fabricado totalmente por medida, adaptado às características de cada espaço, às necessidades de utilização e às preferências de cada cliente. São desenvolvidas soluções em diferentes estilos, do moderno ao contemporâneo, com especial atenção aos materiais, proporções, acabamentos e funcionalidade. Cada peça é pensada para se integrar no espaço, conciliando estética, funcionalidade e durabilidade.", "Le mobilier est entièrement fabriqué sur mesure, en fonction des caractéristiques de chaque espace, de son usage et des préférences de chaque client. Des solutions de styles variés, du moderne au contemporain, sont développées avec une attention particulière portée aux matériaux, aux proportions, aux finitions et à la fonctionnalité. Chaque pièce est pensée pour s’intégrer dans l’espace, en alliant esthétique, fonctionnalité et durabilité.", "All furniture is made to measure, tailored to the characteristics of each space, its intended use and each client’s preferences. Solutions span a range of styles, from modern to contemporary, with particular attention to materials, proportions, finishes and functionality. Every piece is designed to fit naturally into its setting, combining aesthetics, practicality and lasting quality."], ["Cada cliente traz uma visão, uma necessidade e uma forma própria de imaginar o seu espaço. É a partir dessa individualidade que cada projeto ganha identidade, o que resulta numa solução autêntica e verdadeiramente pessoal.", "Chaque client apporte une vision, un besoin et sa propre façon d’imaginer son espace. C’est à partir de cette singularité que chaque projet trouve son identité et devient une solution authentique et véritablement personnelle.", "Every client brings a vision, a need and their own way of imagining their space. It is this individuality that gives each project its identity, resulting in an authentic and truly personal solution."]]);
for(const name of ['Catálogo','Contactos']){const row=rows.find(r=>r[0]===name),brand=rows.find(r=>r[0].startsWith('CAPIARCOS -'));rows.push([`${name} | ${brand[0]}`,`${row[1]} | ${brand[1]}`,`${row[2]} | ${brand[2]}`]);}
for(const name of ['Cozinhas','Roupeiros','Móveis de TV','Quartos','Casas de banho','Ripados','Mesas','Portas','Escadas','Aparadores','Escritórios','Estantes']){const r=rows.find(r=>r[0]===name);rows.push([`${name} — explorar o catálogo`,`${r[1]} — explorer le catalogue`,`${r[2]} — explore the catalogue`]);}
export const languages=['pt','fr','en'];
export const dictionaries={pt:{},fr:Object.fromEntries(rows.map(r=>[r[0],r[1]])),en:Object.fromEntries(rows.map(r=>[r[0],r[2]]))};
export function translate(source,lang='pt'){return dictionaries[lang]?.[source]||source;}
export function language(value){return languages.includes(value)?value:'pt';}
